CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE evidence (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, filename TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', mime TEXT NOT NULL, size INTEGER NOT NULL, stored_path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'uploaded', category TEXT NOT NULL DEFAULT 'unknown', created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, evidence_id TEXT REFERENCES evidence(id) ON DELETE CASCADE, status TEXT NOT NULL, provider TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE job_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, name TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE findings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, evidence_id TEXT REFERENCES evidence(id) ON DELETE SET NULL, title TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'observation', origin TEXT NOT NULL DEFAULT 'fixture', confidence REAL, state TEXT NOT NULL DEFAULT 'suggested', edited_title TEXT, edited_detail TEXT, source_ref TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, finding_id TEXT REFERENCES findings(id) ON DELETE SET NULL, action TEXT NOT NULL, previous_state TEXT, new_state TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE reports (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX evidence_project_idx ON evidence(project_id);
CREATE INDEX findings_project_idx ON findings(project_id);
